  let high = noise(p / 3.5);
  let grain = (low - 0.5) * 0.65 + (high - 0.5) * 0.35;
  let warm_rgb = vec3f(0.88, 0.82, 0.72);
  let warm_a = clamp(uniforms.intensity * 0.65, 0.0, 1.0);
